contracts/ComplianceRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title ComplianceRegistry
 * @notice On-chain KYC whitelist for RWA token holders.
 *         Only KYC-verified addresses may receive/hold RWA tokens.
 */
contract ComplianceRegistry is AccessControl {
    bytes32 public constant KYC_OPERATOR_ROLE = keccak256("KYC_OPERATOR_ROLE");

    struct InvestorInfo {
        bool    verified;
        string  jurisdiction; // ISO country code, e.g. "VN", "SG"
        uint256 verifiedAt;
        uint256 expiresAt;    // 0 = no expiry
    }

    mapping(address => InvestorInfo) private _investors;

    event KYCGranted(address indexed investor, string jurisdiction, uint256 expiresAt);
    event KYCRevoked(address indexed investor);

    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(KYC_OPERATOR_ROLE, admin);
    }

    /// @notice Verify an investor (called by backend after off-chain KYC passes)
    function setKYCStatus(
        address investor,
        bool    verified,
        string calldata jurisdiction,
        uint256 expiresAt
    ) external onlyRole(KYC_OPERATOR_ROLE) {
        if (verified) {
            _investors[investor] = InvestorInfo({
                verified:     true,
                jurisdiction: jurisdiction,
                verifiedAt:   block.timestamp,
                expiresAt:    expiresAt
            });
            emit KYCGranted(investor, jurisdiction, expiresAt);
        } else {
            delete _investors[investor];
            emit KYCRevoked(investor);
        }
    }

    /// @notice Batch-verify multiple investors in one tx (gas-efficient onboarding)
    function batchSetKYC(
        address[] calldata investors,
        string  calldata jurisdiction
    ) external onlyRole(KYC_OPERATOR_ROLE) {
        for (uint256 i = 0; i < investors.length; i++) {
            _investors[investors[i]] = InvestorInfo({
                verified:     true,
                jurisdiction: jurisdiction,
                verifiedAt:   block.timestamp,
                expiresAt:    0
            });
            emit KYCGranted(investors[i], jurisdiction, 0);
        }
    }

    /// @notice Returns true if address is KYC-verified and not expired
    function isVerified(address investor) external view returns (bool) {
        InvestorInfo storage info = _investors[investor];
        if (!info.verified) return false;
        if (info.expiresAt != 0 && block.timestamp > info.expiresAt) return false;
        return true;
    }

    function getInvestorInfo(address investor) external view returns (InvestorInfo memory) {
        return _investors[investor];
    }
}

contracts/ProfitDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./RWAToken.sol";

/**
 * @title ProfitDistributor
 * @notice Automatic dividend distribution for RWA token holders.
 *
 * Algorithm: "Dividend-Per-Share" (same as Synthetix StakingRewards)
 *   - accRewardPerToken: accumulates profit per token over time
 *   - Each holder's pending = balance × (acc - debtAt(holder))
 *   - O(1) per claim regardless of number of holders
 *
 * Usage flow:
 *   1. Asset manager calls depositProfit(amount) monthly with rental income / bond coupon
 *   2. Investors call claimReward() any time to receive accumulated dividends in ETH
 */
contract ProfitDistributor is AccessControl, ReentrancyGuard, Pausable {
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    uint256 private constant PRECISION = 1e18;

    RWAToken public immutable token;

    /* ── Reward tracking ────────────────────────────────────────── */
    uint256 public accRewardPerToken;          // accumulated reward per token (× PRECISION)
    mapping(address => uint256) public rewardDebt;   // user's last-seen accRewardPerToken
    mapping(address => uint256) public claimedTotal; // lifetime claimed per user

    /* ── Stats ──────────────────────────────────────────────────── */
    uint256 public totalProfitDeposited;
    uint256 public totalProfitClaimed;

    struct Distribution {
        uint256 amount;
        uint256 timestamp;
        string  periodDescription; // e.g., "Rental income March 2026"
    }
    Distribution[] public distributionHistory;

    /* ── Events ─────────────────────────────────────────────────── */
    event ProfitDeposited(uint256 amount, uint256 accRewardPerToken, string desc);
    event RewardClaimed(address indexed investor, uint256 amount);

    constructor(address token_, address admin, address factory_) {
        token = RWAToken(token_);
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(OPERATOR_ROLE, admin);
        // Grant factory temp admin so it can grantRole(OPERATOR) to operator wallet
        if (factory_ != address(0)) {
            _grantRole(DEFAULT_ADMIN_ROLE, factory_);
        }
    }

    receive() external payable {}

    /* ── Deposit profit (called by asset manager / operator) ─────── */
    /**
     * @notice Deposit profit to be distributed pro-rata to all token holders.
     * @param desc Human-readable description (e.g., "Q1 2026 rental income")
     */
    function depositProfit(string calldata desc) external payable onlyRole(OPERATOR_ROLE) {
        require(msg.value > 0, "ProfitDistributor: zero deposit");
        uint256 supply = token.totalSupply();
        require(supply > 0, "ProfitDistributor: no tokens issued yet");

        accRewardPerToken += (msg.value * PRECISION) / supply;
        totalProfitDeposited += msg.value;

        distributionHistory.push(Distribution({
            amount:            msg.value,
            timestamp:         block.timestamp,
            periodDescription: desc
        }));

        emit ProfitDeposited(msg.value, accRewardPerToken, desc);
    }

    /* ── Claim reward (called by token holders) ──────────────────── */
    /**
     * @notice Claim accumulated dividends. Callable any time.
     *         Includes both live DPS rewards AND any credits saved during token transfers.
     */
    function claimReward() external nonReentrant whenNotPaused {
        uint256 pending = pendingReward(msg.sender);
        require(pending > 0, "ProfitDistributor: nothing to claim");

        // Reset both DPS debt and saved credit
        rewardDebt[msg.sender]   = accRewardPerToken;
        pendingCredit[msg.sender] = 0;
        claimedTotal[msg.sender] += pending;
        totalProfitClaimed       += pending;

        (bool ok,) = payable(msg.sender).call{value: pending}("");
        require(ok, "ProfitDistributor: ETH transfer failed");

        emit RewardClaimed(msg.sender, pending);
    }

    /* ── View: pending reward ────────────────────────────────────── */
    /**
     * @param investor Address to query
     * @return Total claimable ETH in wei (live DPS rewards + saved transfer credits)
     */
    function pendingReward(address investor) public view returns (uint256) {
        uint256 balance    = token.balanceOf(investor);
        uint256 unrealized = balance > 0
            ? (balance * (accRewardPerToken - rewardDebt[investor])) / PRECISION
            : 0;
        // Add any credits saved during token transfers
        return unrealized + pendingCredit[investor];
    }

    /* ── Pending credits (rewards preserved when debt is reset on transfer) */
    mapping(address => uint256) public pendingCredit; // wei saved before debt reset

    /* ── Hook: update debt on token transfer ─────────────────────── */
    /**
     * @notice Called by RWAToken._update() BEFORE every balance change.
     *         Settles reward debt for both parties so DPS accounting stays correct.
     *
     *   Sender: compute pending with OLD balance → save as credit → reset debt
     *   Receiver: set debt to current acc → they only earn from this point forward
     *
     * @dev Only callable by the linked RWAToken contract.
     */
    function settleOnTransfer(address from, address to) external {
        require(msg.sender == address(token), "ProfitDistributor: only token");

        // ── Settle sender's accrued reward with their CURRENT balance ──
        if (from != address(0)) {
            uint256 balance = token.balanceOf(from);
            if (balance > 0) {
                uint256 unrealized = accRewardPerToken - rewardDebt[from];
                uint256 pending    = (balance * unrealized) / PRECISION;
                if (pending > 0) {
                    // Save as a claimable credit so it isn't lost after the transfer
                    pendingCredit[from] += pending;
                }
            }
            // Reset debt to current acc — after transfer their share changes
            rewardDebt[from] = accRewardPerToken;
        }

        // ── Initialize receiver's debt so they earn only from this point ──
        if (to != address(0)) {
            // First save any existing credit before resetting (handles repeat transfers)
            uint256 existingBalance = token.balanceOf(to);
            if (existingBalance > 0) {
                uint256 unrealized = accRewardPerToken - rewardDebt[to];
                uint256 pending    = (existingBalance * unrealized) / PRECISION;
                if (pending > 0) {
                    pendingCredit[to] += pending;
                }
            }
            rewardDebt[to] = accRewardPerToken;
        }
    }

    /* ── Admin ───────────────────────────────────────────────────── */
    function pause()   external onlyRole(OPERATOR_ROLE) { _pause(); }
    function unpause() external onlyRole(OPERATOR_ROLE) { _unpause(); }

    /// @notice Emergency: withdraw stuck ETH (e.g. from a bad deposit)
    function emergencyWithdraw(uint256 amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        (bool ok,) = payable(msg.sender).call{value: amount}("");
        require(ok, "ProfitDistributor: withdraw failed");
    }

    /* ── View: history ──────────────────────────────────────────── */
    function distributionCount() external view returns (uint256) {
        return distributionHistory.length;
    }

    function getDistributionHistory(uint256 from_, uint256 to_)
        external view returns (Distribution[] memory)
    {
        require(to_ <= distributionHistory.length, "out of range");
        Distribution[] memory result = new Distribution[](to_ - from_);
        for (uint256 i = from_; i < to_; i++) {
            result[i - from_] = distributionHistory[i];
        }
        return result;
    }
}

contracts/RWAFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "./RWAToken.sol";
import "./ProfitDistributor.sol";
import "./ComplianceRegistry.sol";

/**
 * @title RWAFactory
 * @notice Deploy RWAToken + ProfitDistributor pairs for each tokenized asset.
 *
 * One call to createAsset() deploys both contracts, grants proper roles, and
 * emits an event the backend indexes to track all assets on-chain.
 */
contract RWAFactory is AccessControl {
    bytes32 public constant ISSUER_ROLE = keccak256("ISSUER_ROLE");

    ComplianceRegistry public immutable compliance;
    address            public immutable platformAdmin;

    struct AssetContracts {
        address token;
        address distributor;
        uint256 createdAt;
        bool    active;
    }

    // assetId (UUID as bytes32) → deployed contracts
    mapping(bytes32 => AssetContracts) public assets;
    bytes32[] public allAssetIds;

    event AssetCreated(
        bytes32 indexed assetId,
        address indexed token,
        address indexed distributor,
        string          name,
        RWAToken.AssetType assetType,
        uint256         totalValuationUSD,
        uint256         pricePerTokenUSD
    );
    event AssetDeactivated(bytes32 indexed assetId);

    constructor(address compliance_, address admin) {
        compliance    = ComplianceRegistry(compliance_);
        platformAdmin = admin;
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(ISSUER_ROLE, admin);
    }

    /**
     * @notice Deploy a new RWAToken + ProfitDistributor for a real-world asset.
     * @param assetIdStr     UUID string from backend DB (e.g. "550e8400-e29b-41d4-a716-...")
     * @param name           Token name (e.g. "Q1 HCM Tower - Apt 2101")
     * @param symbol         Token symbol (e.g. "HCMT-2101")
     * @param assetType      Enum: 0=REAL_ESTATE, 1=BOND, 2=EQUITY, 3=COMMODITY
     * @param legalDocIPFS   IPFS CID of legal package
     * @param totalVal       Total asset valuation in USD × 1e6
     * @param pricePerToken  Price per token in USD × 1e6
     * @param operator       Backend wallet that can mint and deposit profits
     */
    function createAsset(
        string           calldata assetIdStr,
        string           calldata name,
        string           calldata symbol,
        RWAToken.AssetType        assetType,
        string           calldata legalDocIPFS,
        uint256                   totalVal,
        uint256                   pricePerToken,
        address                   operator
    ) external onlyRole(ISSUER_ROLE) returns (address tokenAddr, address distAddr) {
        require(totalVal > 0 && pricePerToken > 0, "RWAFactory: invalid valuation");
        require(pricePerToken <= totalVal, "RWAFactory: price > valuation");

        bytes32 assetId = keccak256(abi.encodePacked(assetIdStr));
        require(assets[assetId].token == address(0), "RWAFactory: asset already exists");

        /* ── 1. Deploy RWAToken ──────────────────────────────────────*/
        RWAToken newToken = new RWAToken(
            name, symbol, assetIdStr, assetType,
            legalDocIPFS, totalVal, pricePerToken,
            address(compliance), platformAdmin,
            address(this)  // factory gets temp DEFAULT_ADMIN_ROLE
        );
        tokenAddr = address(newToken);

        // ── 2. Deploy ProfitDistributor ─────────────────────────────
        ProfitDistributor newDist = new ProfitDistributor(tokenAddr, platformAdmin, address(this));
        distAddr = address(newDist);

        // ── 3. Wire token ↔ distributor ─────────────────────────────────
        // RWAToken._update() calls distributor.settleOnTransfer() on every balance change.
        // This must be set before renouncing factory's role (still holds OPERATOR_ROLE via admin).
        newToken.setDistributor(distAddr);

        // ── 4. Grant ISSUER+OPERATOR to operator, then renounce factory's admin ─────
        bytes32 ISSUER   = newToken.ISSUER_ROLE();
        bytes32 OPERATOR = newToken.OPERATOR_ROLE();
        bytes32 DIST_OP  = newDist.OPERATOR_ROLE();
        bytes32 ADMIN    = newToken.DEFAULT_ADMIN_ROLE();

        newToken.grantRole(ISSUER, operator);
        newToken.grantRole(OPERATOR, operator);
        newDist.grantRole(DIST_OP, operator);

        // Renounce factory's temporary DEFAULT_ADMIN_ROLE from both contracts
        newToken.renounceRole(ADMIN, address(this));
        newDist.renounceRole(ADMIN, address(this));

        // ── 4. Record ─────────────────────────────────────────────────
        assets[assetId] = AssetContracts({
            token:       tokenAddr,
            distributor: distAddr,
            createdAt:   block.timestamp,
            active:      true
        });
        allAssetIds.push(assetId);

        emit AssetCreated(assetId, tokenAddr, distAddr, name, assetType, totalVal, pricePerToken);
    }

    function deactivateAsset(bytes32 assetId) external onlyRole(DEFAULT_ADMIN_ROLE) {
        assets[assetId].active = false;
        emit AssetDeactivated(assetId);
    }

    function totalAssets() external view returns (uint256) {
        return allAssetIds.length;
    }
}

